    ctx.strokeStyle = imgEdit ? "#3fd6a0" : active ? "#46b4e6" : "rgba(70,180,230,0.5)";
    ctx.fillStyle = imgEdit ? "rgba(63,214,160,0.08)" : active ? "rgba(70,180,230,0.10)" : "rgba(70,180,230,0.04)";
